package com.hbm.client.missile.completion;
import com.hbm.client.model.*;import com.hbm.entity.missile.EntityMissileBaseNT;import com.hbm.missile.completion.MissileContent.Kind;import com.mojang.blaze3d.vertex.PoseStack;import com.mojang.math.Axis;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.entity.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.entity.Entity;
/** Original HFR meshes, original per-type skin/scale and source watcher orientation. */
public final class MissileRenderer extends EntityRenderer<Entity>{private final Kind kind;public MissileRenderer(EntityRendererProvider.Context context,Kind kind){super(context);this.kind=kind;}public static ResourceLocation texture(Kind kind){return ResourceLocation.parse("hbm:textures/models/missile/"+kind.texture+".png");}public static void model(Kind kind,PoseStack poses,MultiBufferSource buffers,int light,int overlay,boolean cull){var model=LegacyObjModels.INSTANCE.get(Minecraft.getInstance().getResourceManager(),ResourceLocation.parse("hbm:models/"+kind.model+".obj"));poses.pushPose();poses.scale(kind.modelScale(),kind.modelScale(),kind.modelScale());LegacyObjRenderer.renderAll(model,poses,buffers.getBuffer(cull?RenderType.entityCutout(texture(kind)):RenderType.entityCutoutNoCull(texture(kind))),light,overlay,-1,kind==Kind.SHUTTLE?LegacyObjRenderer.Convention.FORGE:kind==Kind.STEALTH?LegacyObjRenderer.Convention.HFR_FLAT:LegacyObjRenderer.Convention.HFR);poses.popPose();}@Override public void render(Entity entity,float yaw,float partial,PoseStack poses,MultiBufferSource buffers,int light){poses.pushPose();float ry=entity.yRotO+(entity.getYRot()-entity.yRotO)*partial-90,rx=entity.xRotO+(entity.getXRot()-entity.xRotO)*partial;poses.mulPose(Axis.YP.rotationDegrees(ry));poses.mulPose(Axis.ZP.rotationDegrees(rx));poses.mulPose(Axis.YN.rotationDegrees(ry));if(kind!=Kind.SHUTTLE&&entity instanceof EntityMissileBaseNT missile)switch(missile.rotation()){case 2->poses.mulPose(Axis.YP.rotationDegrees(90));case 4->poses.mulPose(Axis.YP.rotationDegrees(180));case 3->poses.mulPose(Axis.YP.rotationDegrees(270));}model(kind,poses,buffers,light,net.minecraft.client.renderer.texture.OverlayTexture.NO_OVERLAY,true);poses.popPose();}@Override public ResourceLocation getTextureLocation(Entity entity){return texture(kind);}}
